2	// (compile-once/refine-in-place, cited, dated, isolated behind the reviewed
3	// product-requirements crossing point). The folder is the classifier: the two
4	// reserved names (product-requirements/, sample-data/) have fixed meaning;
5	// everything else under product-wiki/ is wiki space. Fingerprinted by the
6	// standard's one structural constant — the sink.
7	import { SINK_README } from './lib.mjs';
8	import layout from './layout.mjs';
9	import pageSections from './page-sections.mjs';
10	import growthLog from './growth-log.mjs';
11	import sources from './sources.mjs';
12	import freshness from './freshness.mjs';
13	import isolation from './isolation.mjs';
14	import wikiGrowth from './run_daily/wiki-growth.mjs';
15	
16	export default {
17	  id: 'product-wiki',
18	  marker: SINK_README,
19	  detect: (ctx) => ctx.tracked.includes(SINK_README),
20	  prose: 'RULES.md',
21	  // The isolation wall rides the barriers mechanism: this pack requires
22	  // barriers and CONTRIBUTES the fixed barrier as manifest data
23	  // (isolation.mjs — pure data, no cross-pack import; pack-independence).
24	  requires: ['barriers'],
25	  contributes: { barriers: [isolation] },
26	  rules: [layout, pageSections, growthLog, sources, freshness],
27	  run_daily: [wikiGrowth],
28	};

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { wikiPages, hasSection } from './lib.mjs';
3	
4	// Every wiki page carries the growth machinery as top-level sections. `##` is
5	// the contract (a `###` heading deliberately misses); hasSection tolerates
6	// case variation and suffix words ("## Open questions (for the next growth
7	// pass)") and ignores headings inside code fences — an embedded template must
8	// not satisfy the requirement. A non-wiki README inside wiki space (an assets
9	// folder) firing here is by design — assets belong under product-wiki/sample-data/;
10	// a genuine exception uses a reasoned accept.
11	const SECTIONS = ['Sources', 'Growth log', 'Open questions'];
12	
13	const rule = {
14	  id: 'product-wiki-page-sections',
15	  severity: 'blocking',
16	  doc: 'packs/product-wiki/README.md',
17	  description: 'Every wiki page carries Sources, Growth log, and Open questions sections',
18	  why: "the sections are the wiki's audit trail and backlog — without them compile-once/refine-in-place degrades to unsourced, unreviewable rewrites",
19	
20	  run(ctx) {
21	    const out = [];
22	    for (const page of wikiPages(ctx.files)) {
23	      const text = ctx.read(page);
24	      if (text === null) continue;
25	      for (const name of SECTIONS) {
26	        if (!hasSection(text, name)) {
27	          out.push(finding(rule, {
28	            file: page,
29	            what: `wiki page is missing its "## ${name}" section`,
30	            fix: 'add it — every wiki page carries the growth machinery: the citations list, the dated growth log, and the open-questions backlog (an empty "## Open questions" is valid)',
31	          }));
32	        }
33	      }
34	    }
35	    return out;
36	  },
37	};
